    public function __construct(private PDO$pdo){}

    /** @return list<array<string,mixed>> */
    public function installBaselineFormulas(string$o,string$u,string$role):array
    {
        $this->govern($o,$u,$role);$out=[];
        foreach(self::FORMULAS as$key=>[$title,$unit,$expression]){$existing=$this->activeFormula($o,$key,false);$out[]=$existing??$this->publishFormulaVersion($o,$u,$role,['formulaKey'=>$key,'title'=>$title,'unit'=>$unit,'expression'=>$expression,'humanConfirmed'=>true]);}
        usort($out,static fn($a,$b)=>$a['formulaKey']<=>$b['formulaKey']);return$out;
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function publishFormulaVersion(string$o,string$u,string$role,array$input):array
    {
        $this->govern($o,$u,$role);$this->confirmed($input,'analytics_formula_confirmation_required');
        $key=$this->choice($input['formulaKey']??null,array_keys(self::FORMULAS),'analytics_formula_key_invalid');
        $title=$this->text($input['title']??null,220,'analytics_formula_title_required');$unit=$this->text($input['unit']??null,40,'analytics_formula_unit_required');$expression=$this->text($input['expression']??null,1000,'analytics_formula_expression_required');$canonicalExpression=self::FORMULAS[$key][2];if($unit!==self::FORMULAS[$key][1]||str_replace('_',' ',$expression)!==$canonicalExpression)throw new AnalyticsReportingException('analytics_formula_definition_unsupported');$expression=$canonicalExpression;
        $s=$this->pdo->prepare('SELECT COALESCE(MAX(version),0)+1 FROM analytics_kpi_formulas WHERE organisation_id=UNHEX(:o) AND formula_key=:key');$s->execute(['o'=>$o,'key'=>$key]);$version=(int)$s->fetchColumn();$id=Identifier::generate();
        $this->pdo->beginTransaction();try{$this->pdo->prepare("UPDATE analytics_kpi_formulas SET status='superseded' WHERE organisation_id=UNHEX(:o) AND formula_key=:key AND status='active'")->execute(['o'=>$o,'key'=>$key]);$this->pdo->prepare("INSERT INTO analytics_kpi_formulas(id,organisation_id,formula_key,title,unit,expression,version,status,created_by) VALUES(UNHEX(:id),UNHEX(:o),:key,:title,:unit,:expression,:version,'active',UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'key'=>$key,'title'=>$title,'unit'=>$unit,'expression'=>$expression,'version'=>$version,'u'=>$u]);$this->audit($o,$u,'analytics.formula_published','analytics_kpi_formula',$id,['formulaKey'=>$key,'version'=>$version]);$this->pdo->commit();}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
        return$this->formula($o,$id);
    }

    /** @param array<string,mixed>$input @return list<array<string,mixed>> */
    public function calculateProjectKpis(string$o,string$u,string$p,array$input):array
    {
        $project=$this->project($o,$u,$p);$this->confirmed($input,'analytics_kpi_confirmation_required');$asOf=$this->date($input['asOf']??null,'analytics_as_of_invalid');
        $source=$this->sources($o,$p);$definitions=[
            'schedule_variance_days'=>$this->schedule($source['milestone_status']??null),
            'cost_to_complete_cents'=>$this->cost($source['financial_summary']??null),
            'defect_liability_remaining_days'=>$this->defects($source['defect_liability']??null,$asOf),
            'retention_release_readiness_percent'=>$this->retention($source['retention_status']??null),
            'compliance_gap_count'=>$this->compliance($source['compliance_status']??null),
        ];$metrics=[];
        $this->pdo->beginTransaction();try{foreach($definitions as$key=>$calculation){$formula=$this->activeFormula($o,$key,true);$id=Identifier::generate();$sourceIds=$calculation['sourceRecordIds'];$snapshot=['formulaKey'=>$key,'formulaVersion'=>$formula['version'],'value'=>$this->number($calculation['value']),'unit'=>$formula['unit'],'asOf'=>$asOf,'calculation'=>$calculation['detail'],'sourceRecordIds'=>$sourceIds];$sha=hash('sha256',$this->json($snapshot));$this->pdo->prepare('INSERT INTO analytics_kpi_snapshots(id,organisation_id,project_id,formula_id,formula_key,formula_version,value_decimal,unit,as_of_date,calculation,source_record_ids,snapshot_sha256,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:formula),:key,:version,:value,:unit,:as_of,:calculation,:sources,:sha,UNHEX(:u))')->execute(['id'=>$id,'o'=>$o,'p'=>$p,'formula'=>$formula['id'],'key'=>$key,'version'=>$formula['version'],'value'=>$snapshot['value'],'unit'=>$formula['unit'],'as_of'=>$asOf,'calculation'=>$this->json($calculation['detail']),'sources'=>$this->json($sourceIds),'sha'=>$sha,'u'=>$u]);$this->record($o,$p,$u,$project['phase'],'kpi_metric',$formula['title'],'approved',$snapshot+['snapshotId'=>$id,'snapshotSha256'=>$sha],array_merge([$id],$sourceIds));$metrics[]=$snapshot+['id'=>$id,'snapshotSha256'=>$sha];}$this->audit($o,$u,'analytics.kpis_calculated','project',$p,['projectId'=>$p,'asOf'=>$asOf,'metricCount'=>count($metrics),'advisoryOnly'=>true]);$this->pdo->commit();}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$metrics;
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function saveDashboardLayout(string$o,string$u,string$role,string$p,array$input):array
    {
        $this->project($o,$u,$p);$this->govern($o,$u,$role);$this->confirmed($input,'analytics_layout_confirmation_required');$dashboardRole=$this->choice($input['dashboardRole']??null,self::DASHBOARD_ROLES,'analytics_dashboard_role_invalid');$keys=$input['widgetKeys']??null;if(!is_array($keys)||$keys===[])throw new AnalyticsReportingException('analytics_widget_keys_required');$keys=array_values(array_unique(array_map(fn($v)=>$this->choice($v,array_keys(self::FORMULAS),'analytics_widget_key_invalid'),$keys)));$refresh=$this->integer($input['refreshSeconds']??60,30,3600,'analytics_refresh_invalid');$s=$this->pdo->prepare('SELECT COALESCE(MAX(version),0)+1 FROM analytics_dashboard_layouts WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND dashboard_role=:role');$s->execute(['o'=>$o,'p'=>$p,'role'=>$dashboardRole]);$version=(int)$s->fetchColumn();$id=Identifier::generate();$this->pdo->beginTransaction();try{$this->pdo->prepare("UPDATE analytics_dashboard_layouts SET status='superseded' WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND dashboard_role=:role AND status='active'")->execute(['o'=>$o,'p'=>$p,'role'=>$dashboardRole]);$this->pdo->prepare("INSERT INTO analytics_dashboard_layouts(id,organisation_id,project_id,dashboard_role,widget_keys,refresh_seconds,version,status,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:role,:keys,:refresh,:version,'active',UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$p,'role'=>$dashboardRole,'keys'=>$this->json($keys),'refresh'=>$refresh,'version'=>$version,'u'=>$u]);$this->audit($o,$u,'analytics.dashboard_layout_saved','analytics_dashboard_layout',$id,['projectId'=>$p,'dashboardRole'=>$dashboardRole,'version'=>$version]);$this->pdo->commit();}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->layout($o,$p,$id);
    }

    /** @return array<string,mixed> */
    public function dashboard(string$o,string$u,string$role,string$p,string$dashboardRole):array
    {
        $this->project($o,$u,$p);$dashboardRole=$this->choice($dashboardRole,self::DASHBOARD_ROLES,'analytics_dashboard_role_invalid');$layout=$this->activeLayout($o,$p,$dashboardRole);$keys=$layout['widgetKeys']??$this->defaultWidgets($dashboardRole);$latest=$this->latestMetrics($o,$p);$widgets=[];foreach($keys as$key){$metric=$latest[$key]??null;$widgets[]=['key'=>$key,'title'=>self::FORMULAS[$key][0],'value'=>$metric['value']??null,'unit'=>self::FORMULAS[$key][1],'metric'=>$metric,'dataAvailable'=>$metric!==null];}return['projectId'=>$p,'dashboardRole'=>$dashboardRole,'layout'=>$layout??['widgetKeys'=>$keys,'refreshSeconds'=>60,'version'=>0],'widgets'=>$widgets,'generatedAt'=>(new DateTimeImmutable('now'))->format(DATE_ATOM),'advisoryOnly'=>true,'formalApprovalChanged'=>false];
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function createAlertRule(string$o,string$u,string$role,string$p,array$input):array
    {
        $this->project($o,$u,$p);$this->govern($o,$u,$role);$this->confirmed($input,'analytics_alert_rule_confirmation_required');$id=Identifier::generate();$name=$this->text($input['name']??null,220,'analytics_alert_name_required');$recordType=$this->text($input['recordType']??null,100,'analytics_alert_record_type_required');$path=$this->path($input['payloadPath']??null);$operator=$this->choice($input['operator']??null,['equals','not_equals','greater_than','less_than','contains'],'analytics_alert_operator_invalid');$severity=$this->choice($input['severity']??null,['low','medium','high','critical'],'analytics_alert_severity_invalid');$recipient=$this->text($input['recipientRole']??null,60,'analytics_alert_recipient_required');$throttle=$this->integer($input['throttleMinutes']??60,1,10080,'analytics_alert_throttle_invalid');$comparison=$input['comparisonValue']??null;
        $this->pdo->prepare("INSERT INTO analytics_alert_rules(id,organisation_id,project_id,name,record_type,payload_path,comparison_operator,comparison_value,severity,recipient_role,throttle_minutes,status,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:name,:type,:path,:operator,:comparison,:severity,:recipient,:throttle,'active',UNHEX(:u))")->execute(['id'=>$id,'o'=>$o,'p'=>$p,'name'=>$name,'type'=>$recordType,'path'=>$path,'operator'=>$operator,'comparison'=>$this->json($comparison),'severity'=>$severity,'recipient'=>$recipient,'throttle'=>$throttle,'u'=>$u]);$this->audit($o,$u,'analytics.alert_rule_created','analytics_alert_rule',$id,['projectId'=>$p]);return$this->alertRule($o,$p,$id);
    }

    /** @param array<string,mixed>$input @return list<array<string,mixed>> */
    public function evaluateAlerts(string$o,string$u,string$p,array$input):array
    {
        $this->project($o,$u,$p);$this->confirmed($input,'analytics_alert_evaluation_confirmation_required');$rules=$this->rows("SELECT HEX(id) id,name,record_type,payload_path,comparison_operator,comparison_value,severity,recipient_role,throttle_minutes FROM analytics_alert_rules WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND status='active' ORDER BY created_at",['o'=>$o,'p'=>$p]);$created=[];
        foreach($rules as$rule){$records=$this->rows('SELECT HEX(id) id,title,payload FROM project_records WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND record_type=:type ORDER BY created_at DESC',['o'=>$o,'p'=>$p,'type'=>$rule['record_type']]);foreach($records as$record){$payload=$this->decode($record['payload']);$actual=$this->nested($payload,(string)$rule['payload_path']);$comparison=$this->decodeValue($rule['comparison_value']);if(!$this->matches($actual,(string)$rule['comparison_operator'],$comparison))continue;$since=(new DateTimeImmutable('now'))->modify('-'.(int)$rule['throttle_minutes'].' minutes')->format('Y-m-d H:i:s.u');$s=$this->pdo->prepare('SELECT 1 FROM analytics_alert_events WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND rule_id=UNHEX(:rule) AND source_record_id=UNHEX(:source) AND created_at>=:since LIMIT 1');$s->execute(['o'=>$o,'p'=>$p,'rule'=>$rule['id'],'source'=>$record['id'],'since'=>$since]);if($s->fetchColumn()!==false)continue;$alertId=Identifier::generate();$inboxId=Identifier::generate();$eventPayload=['alertId'=>$alertId,'ruleId'=>strtolower($rule['id']),'sourceRecordId'=>strtolower($record['id']),'acknowledgementRequired'=>true,'advisoryOnly'=>true,'formalApprovalChanged'=>false];$this->pdo->beginTransaction();try{$this->pdo->prepare("INSERT INTO inbox_items(id,organisation_id,project_id,assigned_role,event_type,title,detail,priority,status,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:role,'analytics.alert',:title,:detail,:priority,'open',:payload)")->execute(['id'=>$inboxId,'o'=>$o,'p'=>$p,'role'=>$rule['recipient_role'],'title'=>$rule['name'],'detail'=>'Analytics detected a configured condition on '.$record['title'].'. Acknowledge this advisory alert; formal approvals remain unchanged.','priority'=>$rule['severity'],'payload'=>$this->json($eventPayload)]);$this->pdo->prepare("INSERT INTO analytics_alert_events(id,organisation_id,project_id,rule_id,source_record_id,inbox_item_id,status,acknowledgement_required) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:rule),UNHEX(:source),UNHEX(:inbox),'open',TRUE)")->execute(['id'=>$alertId,'o'=>$o,'p'=>$p,'rule'=>$rule['id'],'source'=>$record['id'],'inbox'=>$inboxId]);$this->audit($o,$u,'analytics.alert_created','analytics_alert_event',$alertId,['projectId'=>$p,'ruleId'=>$rule['id'],'sourceRecordId'=>$record['id']]);$this->pdo->commit();}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}$created[]=$this->alertEvent($o,$p,$alertId);}}
        return$created;
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function acknowledgeAlert(string$o,string$u,string$id,array$input):array
    {
        $this->confirmed($input,'analytics_alert_acknowledgement_required');$note=$this->text($input['note']??null,1000,'analytics_alert_note_required');$alert=$this->alertEvent($o,null,$id);$this->project($o,$u,$alert['projectId']);$role=$this->membershipRole($o,$u);if(!in_array($role,['owner','admin',$alert['recipientRole']],true))throw new AnalyticsReportingException('analytics_alert_permission_denied');if($alert['status']!=='open')throw new AnalyticsReportingException('analytics_alert_immutable');$this->pdo->beginTransaction();try{$this->pdo->prepare("UPDATE analytics_alert_events SET status='acknowledged',acknowledged_by=UNHEX(:u),acknowledgement_note=:note,acknowledged_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND status='open'")->execute(['u'=>$u,'note'=>$note,'id'=>$id,'o'=>$o]);$this->pdo->prepare("UPDATE inbox_items SET status='resolved',resolved_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id)")->execute(['id'=>$alert['inboxItemId']]);$this->audit($o,$u,'analytics.alert_acknowledged','analytics_alert_event',$id,['projectId'=>$alert['projectId'],'formalApprovalChanged'=>false]);$this->pdo->commit();}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->alertEvent($o,$alert['projectId'],$id)+['formalApprovalChanged'=>false];
    }

    /** @param array<string,mixed>$input @return array<string,mixed> */
    public function recordObservability(string$o,string$u,string$role,array$input):array
    {
        $this->govern($o,$u,$role);$this->confirmed($input,'analytics_observability_confirmation_required');$module=$this->text($input['moduleKey']??null,100,'analytics_observability_module_required');$type=$this->choice($input['metricType']??null,self::METRIC_TYPES,'analytics_observability_type_invalid');$value=$input['metricValue']??null;if(!is_int($value)&&!is_float($value)&&!(is_string($value)&&is_numeric($value)))throw new AnalyticsReportingException('analytics_observability_value_invalid');$days=$this->integer($input['retentionDays']??30,1,365,'analytics_observability_retention_invalid');$context=$input['technicalContext']??null;if(!is_array($context))throw new AnalyticsReportingException('analytics_observability_context_invalid');$allowed=['route','operation','statusCode','requestId','boundaryKey'];foreach($context as$key=>$item)if(!is_string($key)||!in_array($key,$allowed,true)||(!is_scalar($item)&&$item!==null))throw new AnalyticsReportingException('analytics_observability_context_forbidden');$id=Identifier::generate();$until=(new DateTimeImmutable('today'))->modify('+'.$days.' days')->format('Y-m-d');$this->pdo->prepare('INSERT INTO analytics_observability_metrics(id,organisation_id,module_key,metric_type,metric_value,technical_context,retention_until,recorded_by) VALUES(UNHEX(:id),UNHEX(:o),:module,:type,:value,:context,:until,UNHEX(:u))')->execute(['id'=>$id,'o'=>$o,'module'=>$module,'type'=>$type,'value'=>$value,'context'=>$this->json($context),'until'=>$until,'u'=>$u]);$this->audit($o,$u,'analytics.observability_recorded','analytics_observability_metric',$id,['metricType'=>$type,'retentionUntil'=>$until]);return$this->observability($o,$id);
    }

    /** @return array<string,mixed> */
    public function workspace(string$o,string$u,string$role,string$p):array
    {
        $this->project($o,$u,$p);$dashboardRole=in_array($role,['owner','admin'],true)?'admin':($role==='viewer'?'client':'professional');$formulaRows=$this->rows("SELECT HEX(id) id,formula_key,title,unit,expression,version,status,created_at FROM analytics_kpi_formulas WHERE organisation_id=UNHEX(:o) ORDER BY formula_key,version DESC",['o'=>$o]);$layouts=$this->rows("SELECT HEX(id) id,dashboard_role,widget_keys,refresh_seconds,version,status,created_at FROM analytics_dashboard_layouts WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY dashboard_role,version DESC",['o'=>$o,'p'=>$p]);$rules=$this->rows("SELECT HEX(id) id,name,record_type,payload_path,comparison_operator,comparison_value,severity,recipient_role,throttle_minutes,status,created_at FROM analytics_alert_rules WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at DESC",['o'=>$o,'p'=>$p]);$alerts=$this->rows("SELECT HEX(a.id) id,HEX(a.project_id) project_id,HEX(a.rule_id) rule_id,HEX(a.source_record_id) source_record_id,HEX(a.inbox_item_id) inbox_item_id,a.status,a.acknowledgement_required,a.acknowledgement_note,a.created_at,a.acknowledged_at,r.name,r.severity,r.recipient_role FROM analytics_alert_events a JOIN analytics_alert_rules r ON r.id=a.rule_id WHERE a.organisation_id=UNHEX(:o) AND a.project_id=UNHEX(:p) ORDER BY a.created_at DESC",['o'=>$o,'p'=>$p]);$observability=in_array($role,['owner','admin'],true)?$this->rows("SELECT HEX(id) id,module_key,metric_type,metric_value,technical_context,retention_until,created_at FROM analytics_observability_metrics WHERE organisation_id=UNHEX(:o) AND retention_until>=UTC_DATE() ORDER BY created_at DESC LIMIT 100",['o'=>$o]):[];
        return['projectId'=>$p,'dashboard'=>$this->dashboard($o,$u,$role,$p,$dashboardRole),'latestMetrics'=>array_values($this->latestMetrics($o,$p)),'formulas'=>array_map($this->normaliseFormula(...),$formulaRows),'layouts'=>array_map($this->normaliseLayout(...),$layouts),'alertRules'=>array_map($this->normaliseRule(...),$rules),'alertEvents'=>array_map($this->normaliseAlert(...),$alerts),'observability'=>array_map($this->normaliseObservability(...),$observability),'boundaries'=>['advisoryOnly'=>true,'formalApprovalMutationAllowed'=>false,'exportsTenantScoped'=>true,'observabilityContainsRawPersonalContent'=>false]];
    }

    /** @return array{filename:string,mimeType:string,content:string,sha256:string} */
    public function export(string$o,string$u,string$p,string$type,string$format,?string$from,?string$to):array
    {
        $this->project($o,$u,$p);$type=$this->choice($type,['project_records','inbox','audit'],'analytics_export_type_invalid');$format=$this->choice($format,['csv','json'],'analytics_export_format_invalid');$from=$this->date($from??'2000-01-01','analytics_export_from_invalid');$to=$this->date($to??'2100-12-31','analytics_export_to_invalid');if($from>$to)throw new AnalyticsReportingException('analytics_export_range_invalid');
        if($type==='project_records')$rows=$this->rows('SELECT HEX(id) id,HEX(project_id) project_id,module_key,record_type,title,status,payload,created_at FROM project_records WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND created_at>=:from AND created_at<DATE_ADD(:to,INTERVAL 1 DAY) ORDER BY created_at',['o'=>$o,'p'=>$p,'from'=>$from,'to'=>$to]);
        elseif($type==='inbox')$rows=$this->rows('SELECT HEX(id) id,HEX(project_id) project_id,event_type,title,detail,priority,status,payload,created_at FROM inbox_items WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND created_at>=:from AND created_at<DATE_ADD(:to,INTERVAL 1 DAY) ORDER BY created_at',['o'=>$o,'p'=>$p,'from'=>$from,'to'=>$to]);
        else$rows=$this->rows("SELECT HEX(id) id,action,subject_type,HEX(subject_id) subject_id,metadata,created_at FROM audit_events WHERE organisation_id=UNHEX(:o) AND created_at>=:from AND created_at<DATE_ADD(:to,INTERVAL 1 DAY) AND (JSON_UNQUOTE(JSON_EXTRACT(metadata,'$.projectId'))=:p OR subject_id=UNHEX(:p)) ORDER BY created_at",['o'=>$o,'p'=>$p,'from'=>$from,'to'=>$to]);
        $rows=array_map(function(array$row):array{foreach(['payload','metadata']as$key)if(isset($row[$key]))$row[$key]=$this->redact($this->decode($row[$key]));return$row;},$rows);if($format==='json'){$content=json_encode($rows,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$mime='application/json';}else{$stream=fopen('php://temp','w+b');$headers=$rows!==[]?array_keys($rows[0]):['id'];fputcsv($stream,$headers);foreach($rows as$row)fputcsv($stream,array_map(fn($v)=>is_array($v)?$this->json($v):(string)$v,$row));rewind($stream);$content=(string)stream_get_contents($stream);fclose($stream);$mime='text/csv';}$filename='analytics-'.$type.'-'.$from.'-'.$to.'.'.$format;$this->audit($o,$u,'analytics.export_generated','project',$p,['projectId'=>$p,'type'=>$type,'format'=>$format,'from'=>$from,'to'=>$to,'rowCount'=>count($rows)]);return['filename'=>$filename,'mimeType'=>$mime,'content'=>$content,'sha256'=>hash('sha256',$content)];
    }

    /** @return array<string,mixed> */ private function project(string$o,string$u,string$p):array{$s=$this->pdo->prepare("SELECT pr.current_phase phase FROM projects pr JOIN organisation_memberships m ON m.organisation_id=pr.organisation_id AND m.user_id=UNHEX(:u) AND m.status='active' WHERE pr.id=UNHEX(:p) AND pr.organisation_id=UNHEX(:o)");$s->execute(['u'=>$u,'p'=>$p,'o'=>$o]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($row))throw new AnalyticsReportingException('analytics_project_not_found');return$row;}
    private function govern(string$o,string$u,string$role):void{if(!in_array($role,['owner','admin'],true)||$this->membershipRole($o,$u)!==$role)throw new AnalyticsReportingException('analytics_governance_permission_denied');}
    private function membershipRole(string$o,string$u):string{$s=$this->pdo->prepare("SELECT role FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);$role=$s->fetchColumn();if(!is_string($role))throw new AnalyticsReportingException('analytics_membership_not_found');return$role;}
    /** @return array<string,array<string,mixed>> */ private function sources(string$o,string$p):array{$rows=$this->rows("SELECT HEX(id) id,record_type,payload FROM project_records WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND record_type IN ('milestone_status','financial_summary','defect_liability','retention_status','compliance_status') ORDER BY created_at DESC",['o'=>$o,'p'=>$p]);$out=[];foreach($rows as$row)if(!isset($out[$row['record_type']]))$out[$row['record_type']]=['id'=>strtolower($row['id']),'payload'=>$this->decode($row['payload'])];return$out;}
    /** @return array{value:int|float,detail:array<string,mixed>,sourceRecordIds:list<string>} */ private function schedule(?array$s):array{$p=$s['payload']??[];$planned=$p['plannedDate']??null;$actual=$p['actualDate']??($p['forecastDate']??null);$value=is_string($planned)&&is_string($actual)?(int)(new DateTimeImmutable($planned))->diff(new DateTimeImmutable($actual))->format('%r%a'):0;return['value'=>$value,'detail'=>['plannedDate'=>$planned,'actualOrForecastDate'=>$actual,'missingSource'=>$s===null],'sourceRecordIds'=>$s?[$s['id']]:[]];}
