    /** @return array<string,mixed>|null */ private function activeFormula(string$o,string$key,bool$required):?array{$s=$this->pdo->prepare("SELECT HEX(id) id,formula_key,title,unit,expression,version,status,created_at FROM analytics_kpi_formulas WHERE organisation_id=UNHEX(:o) AND formula_key=:key AND status='active' ORDER BY version DESC LIMIT 1");$s->execute(['o'=>$o,'key'=>$key]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($row)){if($required)throw new AnalyticsReportingException('analytics_formula_not_found');return null;}return$this->normaliseFormula($row);}
