    private function layout(string$o,string$p,string$id):array{$s=$this->pdo->prepare('SELECT HEX(id) id,dashboard_role,widget_keys,refresh_seconds,version,status,created_at FROM analytics_dashboard_layouts WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND id=UNHEX(:id)');$s->execute(['o'=>$o,'p'=>$p,'id'=>$id]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($r))throw new AnalyticsReportingException('analytics_layout_not_found');return$this->normaliseLayout($r);}
