    private function alertEvent(string$o,?string$p,string$id):array{$sql="SELECT HEX(a.id) id,HEX(a.project_id) project_id,HEX(a.rule_id) rule_id,HEX(a.source_record_id) source_record_id,HEX(a.inbox_item_id) inbox_item_id,a.status,a.acknowledgement_required,a.acknowledgement_note,a.created_at,a.acknowledged_at,r.name,r.severity,r.recipient_role FROM analytics_alert_events a JOIN analytics_alert_rules r ON r.id=a.rule_id WHERE a.organisation_id=UNHEX(:o) AND a.id=UNHEX(:id)".($p!==null?' AND a.project_id=UNHEX(:p)':'');$params=['o'=>$o,'id'=>$id];if($p!==null)$params['p']=$p;$s=$this->pdo->prepare($sql);$s->execute($params);$r=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($r))throw new AnalyticsReportingException('analytics_alert_not_found');return$this->normaliseAlert($r);}
